package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;import io.knowledgebrain.contracts.collaboration.courseenrollment.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class CourseEnrollmentStoreIntegrationTest {
 CourseStoreIntegrationTest parent;GroupStoreIntegrationTest f;CourseEnrollmentStore store;UUID group,space,course,participant;
 @BeforeEach void setup(){parent=new CourseStoreIntegrationTest();parent.setup();f=parent.f;group=parent.group;space=parent.space;var study=parent.study();var selected=parent.curriculum(parent.create(f.key()).course(),study.studyId());course=parent.state(selected,"ACTIVE").courseId();participant=f.ids.next();store=new CourseEnrollmentStore(f.source,parent.store,Clock.systemUTC());}
 CourseEnrollmentStore.Enrollment change(long version,String state){return store.change(group,space,course,participant,version,state,f.trace);}
 void status(int code,org.junit.jupiter.api.function.Executable op){parent.status(code,op);}
 @Test void sentinelDoesNotWriteAndEnrollmentAuditPinsCourseRevisionWithProtobuf()throws Exception{
  var empty=store.mine(group,space,course,participant,true);assertNull(empty.enrollment().enrollmentId());assertEquals(0,empty.enrollment().version());assertEquals("NOT_ENROLLED",empty.enrollment().state());assertTrue(empty.canEnroll());assertEquals(empty.enrollment(),change(0,"WITHDRAWN"));assertTrue(store.list(group,space,course,null,20).items().isEmpty());assertTrue(store.mineHistory(group,space,course,participant,Long.MAX_VALUE,5).items().isEmpty());
  var v=change(0,"ENROLLED");assertEquals(7,v.enrollmentId().version());assertEquals(3,v.courseVersion());assertEquals(1,v.version());assertEquals("PARTICIPANT_AND_OWNER",v.audience());assertEquals(v,store.get(group,space,course,v.enrollmentId(),participant,false));var audit=store.mineHistory(group,space,course,participant,Long.MAX_VALUE,5).items().getFirst();assertEquals(v,audit.snapshot());assertEquals(participant,audit.actorId());assertEquals(3,f.jdbc.queryForObject("SELECT course_version FROM course_enrollment_revision WHERE enrollment_id=?",Long.class,v.enrollmentId()));
  var e=CourseEnrollmentEnvelopeV1.parseFrom(f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,v.enrollmentId()));var p=CourseEnrollmentSnapshotV1.parseFrom(e.getPayload());assertEquals("CourseEnrolled",e.getEventType());assertEquals("CourseEnrollment",e.getAggregateType());assertEquals(participant.toString(),e.getActorId());assertEquals(f.trace,e.getTraceId());assertEquals(space.toString(),e.getSpaceId());assertEquals(v.enrollmentId().toString(),p.getEnrollmentId());assertEquals(3,p.getCourseVersion());assertEquals("PARTICIPANT_AND_OWNER",p.getAudience());assertEquals(3,parent.store.get(group,space,course).version());
 }
 @Test void noOpsRequireCurrentVersionAndLostResponseCanBeRecoveredWithoutReapplying(){var v=change(0,"ENROLLED");assertEquals(v,change(1,"ENROLLED"));status(412,()->change(0,"ENROLLED"));assertEquals(v,new CourseEnrollmentStore(f.source,parent.store,Clock.systemUTC()).mine(group,space,course,participant,true).enrollment());assertEquals(1,parent.events(v.enrollmentId()));var withdrawn=change(1,"WITHDRAWN");status(412,()->change(1,"ENROLLED"));assertEquals(withdrawn,change(2,"WITHDRAWN"));var rejoined=change(2,"ENROLLED");assertEquals(v.enrollmentId(),rejoined.enrollmentId());assertEquals(v.createdAt(),rejoined.createdAt());assertEquals(3,parent.events(v.enrollmentId()));assertEquals(1,store.list(group,space,course,null,20).items().size());}
 @Test void parentLifecycleAllowsOptOutButOnlyActiveCourseAllowsNewEnrollment(){var c=parent.create(f.key()).course();status(409,()->store.change(group,space,c.courseId(),participant,0,"ENROLLED",f.trace));var v=change(0,"ENROLLED");var completed=parent.state(parent.store.get(group,space,course),"COMPLETED");assertFalse(store.mine(group,space,course,participant,true).canEnroll());assertEquals(v,change(1,"ENROLLED"));assertEquals("WITHDRAWN",change(1,"WITHDRAWN").state());status(409,()->change(2,"ENROLLED"));var retired=parent.state(completed,"RETIRED");assertEquals("WITHDRAWN",change(2,"WITHDRAWN").state());var other=f.ids.next();status(409,()->store.change(group,space,course,other,0,"ENROLLED",f.trace));assertEquals(retired,parent.store.get(group,space,course));assertEquals(1,store.mineHistory(group,space,course,participant,2,5).items().size());}
 @Test void enrollmentAndHistoryStayParticipantAndOwnerScoped(){var v=change(0,"ENROLLED");var peer=f.ids.next();status(404,()->store.get(group,space,course,v.enrollmentId(),peer,false));status(404,()->store.history(group,space,course,v.enrollmentId(),peer,false,Long.MAX_VALUE,5));assertEquals(v,store.get(group,space,course,v.enrollmentId(),f.owner,true));status(404,()->store.get(group,f.ids.next(),course,v.enrollmentId(),f.owner,true));status(404,()->store.get(f.ids.next(),space,course,v.enrollmentId(),f.owner,true));var foreign=parent.create(f.key()).course();status(404,()->store.get(group,space,foreign.courseId(),v.enrollmentId(),f.owner,true));assertEquals("NOT_ENROLLED",store.mine(group,space,course,peer,false).enrollment().state());assertFalse(store.mine(group,space,course,peer,false).canEnroll());}
 @Test void keysetCatalogAndDescendingHistoryAreBounded(){var v=change(0,"ENROLLED");change(1,"WITHDRAWN");change(2,"ENROLLED");for(int n=0;n<2;n++)store.change(group,space,course,f.ids.next(),0,"ENROLLED",f.trace);var page=store.list(group,space,course,null,2);assertEquals(2,page.items().size());assertEquals(1,store.list(group,space,course,page.nextAfter(),2).items().size());var h=store.history(group,space,course,v.enrollmentId(),f.owner,true,Long.MAX_VALUE,2);assertEquals(List.of(3L,2L),h.items().stream().map(CourseEnrollmentStore.Revision::version).toList());assertEquals(1,store.mineHistory(group,space,course,participant,h.nextBefore(),2).items().size());}
 @Test void concurrentFirstEnrollmentAndOppositeTransitionsEachHaveOneWinner()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var results=new ArrayList<Future<Boolean>>();for(int n=0;n<2;n++)results.add(pool.submit(()->{barrier.await();try{change(0,"ENROLLED");return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(results.get(0).get(),results.get(1).get());assertEquals(1,store.list(group,space,course,null,20).items().size());var v=store.mine(group,space,course,participant,true).enrollment();assertEquals(1,parent.events(v.enrollmentId()));var a=pool.submit(()->{barrier.await();try{return change(1,"WITHDRAWN");}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return null;}});var b=pool.submit(()->{barrier.await();try{return change(1,"WITHDRAWN");}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return null;}});assertNotEquals(a.get()==null,b.get()==null);assertEquals(2,parent.events(v.enrollmentId()));}}
 @Test void courseCompletionAndFirstEnrollmentSerialize()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return parent.state(parent.store.get(group,space,course),"COMPLETED");});var b=pool.submit(()->{barrier.await();try{return change(0,"ENROLLED");}catch(ResponseStatusException e){assertEquals(409,e.getStatusCode().value());return null;}});assertEquals("COMPLETED",a.get(20,TimeUnit.SECONDS).state());var result=b.get(20,TimeUnit.SECONDS);assertEquals(result==null?0:1,store.mine(group,space,course,participant,true).enrollment().version());}}
 @Test void outboxFailureRollsBackNewAndExistingEnrollmentWithHistory(){String name="enroll_fail_"+course.toString().replace("-","");String check=" CHECK(aggregatetype<>'course-enrollment' OR trace_id<>'"+f.trace+"') NOT VALID";f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(0,"ENROLLED"));assertTrue(store.list(group,space,course,null,20).items().isEmpty());assertTrue(store.mineHistory(group,space,course,participant,Long.MAX_VALUE,5).items().isEmpty());}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}var v=change(0,"ENROLLED");f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+name+check);try{assertThrows(RuntimeException.class,()->change(1,"WITHDRAWN"));assertEquals(v,store.mine(group,space,course,participant,true).enrollment());assertEquals(1,store.mineHistory(group,space,course,participant,Long.MAX_VALUE,5).items().size());assertEquals(1,parent.events(v.enrollmentId()));}finally{f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+name);}}
}
